import json,struct,hashlib,re,collections
from pathlib import Path
out=Path('outputs/stage40l_validation');ram=(out/'controls_ram.bin').read_bytes();base=0x08000000;r=json.loads(Path('outputs/stage40l/width_patch_report.json').read_text());a=int(r['helper_runtime'],0);n=r['helper_size'];actual=ram[a-base:a-base+n];r['runtime_helper_sha1']=hashlib.sha1(actual).hexdigest();r['runtime_helper_matches']=r['runtime_helper_sha1']==r['helper_sha1'];a=int(r['width_call_runtime'],0);r['runtime_width_call_word']=hex(struct.unpack_from('<I',ram,a-base)[0]);r['runtime_width_call_matches']=r['runtime_width_call_word']==r['width_call_runtime_word']
lines=(out/'ppsspp.log').read_text(encoding='utf-8',errors='replace').splitlines();calls=[int(re.search('a1=([0-9a-f]+)',x)[1],16) for x in lines if 'BIA40K' in x];r['width_lookup_trace']={'count':len(calls),'decoded_hangul_calls':sum(0xac00<=x<=0xd7a3 for x in calls),'byte_calls_80_ff':sum(128<=x<256 for x in calls),'examples':[hex(x) for x in list(dict.fromkeys(calls))[:25]]};r['runtime_verified']=r['runtime_helper_matches'] and r['runtime_width_call_matches'] and r['width_lookup_trace']['decoded_hangul_calls']>0 and r['width_lookup_trace']['byte_calls_80_ff']==0
print(json.dumps(r));(out/'width_validation_report.json').write_text(json.dumps(r,indent=2));print(json.dumps({k:r[k] for k in ['runtime_helper_matches','runtime_width_call_matches','width_lookup_trace','runtime_verified']}))

